import numpy as np
import xarray as xr
from satpy.readers.li_base_nc.LiBaseNC import LiBaseNC

class MockLiBaseNC(LiBaseNC):
    def __init__(self):
        # Mocking the initialization to avoid needing actual files
        self.internal_variables = {}
        self.search_paths = []
        self.dataset = None

    def variable_path_exists(self, vpath):
        # Mock this to return True if vpath is in a predefined list
        return vpath in self.existing_vars

    def __getitem__(self, vpath):
        # Mock this to return a dummy xarray object
        return xr.DataArray([1.0], attrs={"_FillValue": -999.0})

    def get_variable_search_paths(self, var_paths):
        return super().get_variable_search_paths(var_paths)

    def get_first_valid_variable(self, var_paths):
        return super().get_first_valid_variable(var_paths)

    def apply_fill_value(self, arr, fill_value):
        return super().apply_fill_value(arr, fill_value)

    def get_measured_variable(self, var_paths, fill_value=np.nan):
        return super().get_measured_variable(var_paths, fill_value)

def test_internal_variable_list():
    reader = MockLiBaseNC()
    reader.internal_variables = {"internal_var": "internal_arr"}

    # Case 1: var_paths is a string and matches internal variable
    # This should work
    try:
        res = reader.get_measured_variable("some_internal_var")
        assert res == "internal_arr"
        print("Case 1 passed")
    except Exception as e:
        print(f"Case 1 failed: {e}")

    # Case 2: var_paths is a list and the FIRST element matches internal variable
    # This should work
    try:
        res = reader.get_measured_variable(["some_internal_var", "other_var"])
        assert res == "internal_arr"
        print("Case 2 passed")
    except Exception as e:
        print(f"Case 2 failed: {e}")

    # Case 3: var_paths is a list and the SECOND element matches internal variable
    # This is where the bug is expected
    try:
        res = reader.get_measured_variable(["other_var", "some_internal_var"])
        assert res == "internal_arr"
        print("Case 3 passed")
    except Exception as e:
        print(f"Case 3 failed: {e}")

if __name__ == "__main__":
    test_internal_variable_list()

